import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {useIssueState} from '@github-ui/issue-pr-state'
import {issuePath} from '@github-ui/paths'
import {Token} from '@primer/react'

import styles from './TrackingIssue.module.css'
import type {TrackingIssueProps} from './types'

export const TrackingIssue = ({number: issueNumber, repository, state, stateReason}: TrackingIssueProps) => {
  const {ownerLogin: owner, name: repo} = repository

  const issueUrl = issuePath({owner, repo, issueNumber})

  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const hovercardAttrs = getHovercardAttributesForType('issue', {owner, repo, issueNumber})

  const {sourceIcon} = useIssueState({state, stateReason})
  const IconComponent = sourceIcon('Issue')

  return (
    <Token
      as="a"
      size="xlarge"
      href={issueUrl}
      leadingVisual={IconComponent}
      className={`${styles.TrackingIssue} bgColor-default text-normal pl-2`}
      aria-label={`Tracked in issue #${issueNumber}`}
      text={`#${issueNumber}`}
      {...hovercardAttrs}
    />
  )
}
