import {ssrSafeDocument} from '@github-ui/ssr-utils'
import type {TrackingIssue} from '@github-ui/code-scanning-shared/types/tracking-link'

export const TRACKING_ISSUE_CHANGED_EVENT_NAME = 'code-scanning-alert-tracking-issue-changed'

export function dispatchTrackingIssueChanged(trackingIssue: TrackingIssue | null) {
  ssrSafeDocument?.dispatchEvent(new CustomEvent(TRACKING_ISSUE_CHANGED_EVENT_NAME, {detail: trackingIssue}))
}

export function onTrackingIssueChanged(callback: (trackingIssue: TrackingIssue | null) => void) {
  const handler = (event: Event) => callback((event as CustomEvent<TrackingIssue | null>).detail)
  ssrSafeDocument?.addEventListener(TRACKING_ISSUE_CHANGED_EVENT_NAME, handler)
  return () => ssrSafeDocument?.removeEventListener(TRACKING_ISSUE_CHANGED_EVENT_NAME, handler)
}
